def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            v_without_build = v.split('+')[0]
        else:
            v_without_build = v

        # Split off pre-release (everything after '-')
        if '-' in v_without_build:
            parts = v_without_build.split('-', 1)
            version_part = parts[0]
            prerelease_part = parts[1]
        else:
            version_part = v_without_build
            prerelease_part = None

        # Parse MAJOR.MINOR.PATCH
        version_nums = tuple(map(int, version_part.split('.')))

        # Parse pre-release identifiers
        if prerelease_part is not None:
            prerelease_identifiers = prerelease_part.split('.')
        else:
            prerelease_identifiers = None

        return version_nums, prerelease_identifiers

    def prerelease_key(identifiers):
        if identifiers is None:
            # No pre-release sorts after pre-release
            return (1, [])

        # Pre-release sorts before release
        converted = []
        for identifier in identifiers:
            if identifier.isdigit():
                # All-digit identifiers compare numerically
                converted.append((0, int(identifier)))
            else:
                # Other identifiers compare by ASCII order
                converted.append((1, identifier))

        return (0, converted)

    def sort_key(indexed_version):
        index, v = indexed_version
        version_nums, prerelease_identifiers = parse_version(v)
        return (version_nums, prerelease_key(prerelease_identifiers), index)

    indexed_versions = list(enumerate(versions))
    indexed_versions.sort(key=sort_key)
    return [v for _, v in indexed_versions]

